def _key(version: str):
    # Split off build metadata (does not affect precedence)
    core = version.split("+", 1)[0]
    # Split off pre-release
    if "-" in core:
        base, pre = core.split("-", 1)
    else:
        base, pre = core, None
    major, minor, patch = (int(x) for x in base.split("."))

    if pre is None:
        # Release ranks above any pre-release of the same version
        pre_key = (1,)
    else:
        ids = []
        for ident in pre.split("."):
            if ident.isdigit():
                ids.append((0, int(ident), ""))
            else:
                ids.append((1, 0, ident))
        # List comparison gives "shorter list is lower" when prefixes equal
        pre_key = (0, ids)
    return (major, minor, patch, pre_key)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_key)

