def _format(national: str) -> str:
    if national.startswith("20"):
        # London: +44 20 7946 0958
        return "%s %s %s" % (national[:2], national[2:6], national[6:])
    if national.startswith(("23", "29")):
        # +44 23 xx xxxx xxxx
        return "%s %s %s %s" % (national[:2], national[2:4], national[4:8], national[8:])
    if national.startswith("7"):
        # Mobile: +44 7700 900123
        return "%s %s" % (national[:4], national[4:])
    if national.startswith("1"):
        if national[:3] in _THREE_DIGIT:
            # e.g. 0113 496 0123
            return "%s %s %s" % (national[:3], national[3:7], national[7:])
        # e.g. 01632 960123
        return "%s %s" % (national[:4], national[4:])
    if national[0] in "389":
        # e.g. 0303 123 7300 / 0800 111 4000
        return "%s %s %s" % (national[:3], national[3:6], national[6:])
    # other 02x area codes: e.g. 02475 831000
    return "%s %s" % (national[:4], national[4:])


def normalize_phone(raw: str) -> str:
    s = raw.strip()
    digits = re.sub(r"\D", "", s)
    invalid = "INVALID"

    if "+" in s:
        after_plus = re.sub(r"\D", "", s[s.index("+") + 1:])
        if not after_plus.startswith("44"):
            return invalid
        rest = after_plus[2:]
    elif digits.startswith("0044"):
        rest = digits[4:]
    elif digits.startswith("00"):
        return invalid  # another international access code
    elif digits.startswith("0"):
        if len(digits) != 11:
            return invalid
        rest = digits[1:]
    else:
        return invalid

    # drop the (0) after the country code
    if rest.startswith("0"):
        rest = rest[1:]
    if len(rest) != 10:
        return invalid

    return "+44 " + _format(rest)

