def wrap_text(text: str, width: int) -> str:
    words = text.split()
    if not words:
        return ""

    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            # End the line in progress, if any.
            if current:
                lines.append(current)
                current = ""
            # Emit the word in pieces of exactly `width` characters.
            for i in range(0, len(word), width):
                piece = word[i:i + width]
                if i + width < len(word):
                    # A full piece gets its own line.
                    lines.append(piece)
                elif len(piece) == width:
                    # Final piece exactly fills a line.
                    lines.append(piece)
                    current = ""
                else:
                    # Shorter final piece starts the next line.
                    current = piece
            continue

        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return "\n".join(lines)

