import re


def rle_encode(s: str) -> str:
    def esc(c: str) -> str:
        return "\\" + c if c in ("(", ")", "\\") else c

    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        length = j - i
        c = esc(s[i])
        # Split a run longer than 99 into pieces of 99 from the left.
        while length > 99:
            out.append("(99*" + c + ")")
            length -= 99
        if length >= 3:
            out.append("(" + str(length) + "*" + c + ")")
        else:
            out.append(c * length)
        i = j
    return "".join(out)

