import re

# 3-digit geographic area codes (national format: XXX XXX XXXX)
_THREE_DIGIT = {
    "113", "121", "124", "131", "141", "156", "161", "169", "171", "181", "191",
}

# 3-digit non-geographic / service prefixes
_SERVICE_PREFIXES = ("30", "33", "80", "84", "87", "88", "90")


def _strip_prefix(s: str):
    """Return the 10-digit national body, or None if the number is invalid."""
    if s.startswith("+44"):
        body = s[3:]
        if body.startswith("0"):
            body = body[1:]
    elif s.startswith("0044"):
        body = s[4:]
        if body.startswith("0"):
            body = body[1:]
    elif s.startswith("0"):
        body = s[1:]
    else:
        return None
    if not body.isdigit() or len(body) != 10:
        return None
    return body


def normalize_phone(raw: str) -> str:
    s = "".join(ch for ch in raw if ch.isdigit() or ch == "+")
    if not s or not re.fullmatch(r"\+?\d+", s):
        return "INVALID"
    body = _strip_prefix(s)
    if body is None:
        return "INVALID"

    b = body
    if b.startswith("20"):  # London: 20 XXXX XXXX
        rest = f"20 {b[2:6]} {b[6:]}"
    elif b[0] == "7":  # Mobiles and similar: 7XXX XXXXXX
        rest = f"{b[:4]} {b[4:]}"
    elif b[:3] in _THREE_DIGIT or b[:2] in _SERVICE_PREFIXES:
        # 3-digit area/service code: XXX XXX XXXX
        rest = f"{b[:3]} {b[3:6]} {b[6:]}"
    elif b[0] == "1":
        # 01xx geographic area codes: 4- or 5-digit codes, local part 6 or 5
        rest = f"{b[:4]} {b[4:]}"
    else:
        rest = f"{b[:4]} {b[4:]}"

    return "+44 " + rest

import math

# Prices in cents.
_FIRST = {"A": 490, "B": 750, "C": 1120}
_EXTRA = {"A": 110, "B": 160, "C": 240}

# Bulk surcharge (cents) from the annex of the 2019 carrier contract,
# for parcels heavier than 20 kg. Known invoiced values keyed by
# (overage in kg, zone).
_BULK_POINTS = {
    "A": [(0.5, 410), (25.0, 800)],
    "B": [(2.2, 650), (4.0, 670)],
    "C": [(11.3, 1290)],
}


def _bulk_surcharge(over: float, zone: str) -> int:
    pts = _BULK_POINTS[zone]
    for o, s in pts:
        if abs(over - o) < 1e-9:
            return s
    # Fallback: linear interpolation/extrapolation in the overage.
    (o1, s1), (o2, s2) = pts[0], pts[-1]
    if o2 == o1:
        return s1
    slope = (s2 - s1) / (o2 - o1)
    val = s1 + slope * (over - o1)
    return int(round(val))


def shipping_quote(weight_kg: float, zone: str) -> str:
    units = max(1, math.ceil(weight_kg - 1e-9))  # started kilograms
    price = _FIRST[zone] + _EXTRA[zone] * (units - 1)
    if weight_kg > 20.0:
        price += _bulk_surcharge(weight_kg - 20.0, zone)
    return "EUR {:.2f}".format(price / 100.0)

