def rle_encode(s: str) -> str:
    def esc(c: str) -> str:
        return "\\" + c if c in "()" or c == "\\" else c

    def encode_run(run: int, c: str) -> str:
        if run < 3:
            return esc(c) * run
        parts = []
        while run > 99:
            parts.append("(99*" + esc(c) + ")")
            run -= 99
        if run >= 3:
            parts.append("(%d*" % run + esc(c) + ")")
        else:
