def rle_encode(s: str) -> str:
    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        c, run = s[i], j - i
        e = "\\" + c if c in "()\\" else c
        if run < 3:
            out.append(e * run)
        else:
            while run > 99:
                out.append(f"(99*{e})")
                run -= 99
            if run >= 3:
                out.append(f"({run}*{e})")
            else:
                out.append(e * run)
        i = j
    return "".join(out)

