def v(c): return int(c,36)
data=[(list(map(v,a['args'][0])), v(a['expected'][8])) for a in d]

# test linear consistency mod 4 and mod 9 via gaussian elimination
def solve_mod(m, data):
    # unknowns w0..w7, equations a.w = c mod m
    M=[row[:] for row in [[r%m for r in s]+[c%m] for s,c in data]]
    n=8; r=0; cols=[]
    for col in range(n):
        piv=None
        for i in range(r,len(M)):
            if M[i][col]%m: piv=i;break
        if piv is None: continue
        M[r],M[piv]=M[piv],M[r]
        inv=pow(M[r][col]// (1), -1, m) if pow(M[r][col],-1,m,None) is not None else None
        # need gcd==1 for true pivot; else handle. Use extended: only works if gcd=1
        try: inv=pow(M[r][col],-1,m)
        except ValueError:
            return None  # not invertible; inconclusive
        f=inv
        M[r]=[x*f%m for x in M[r]]
        for i in range(len(M)):
            if i!=r and M[i][col]%m:
                f=M[i][col]%m
                M[i]=[(a-f*b)%m for a,b in zip(M[i],M[r])]
        r+=1; cols.append(col)
    # check free rows
    for row in M:
        if all(x==0 for x in row[:n]) and row[n]%m!=0: return None
    return (r, M)

for m in (4,9):
    print(m, solve_mod(m, data))
